-- Example hardware telemetry outbox batch
BEGIN;
INSERT INTO hardware_telemetry_raw (message_id, source, node_id, asset_tag, hostname, site_id, rack_id, region, geo_region, event_time, created_at, cpu_temp_c, cpu_util_pct, gpu_temp_c, gpu_util_pct, vram_used_mb, vram_total_mb, mem_used_mb, mem_total_mb, mem_pressure_pct, power_draw_w, fan_rpm, thermal_throttle_active, thermal_throttle_reason, disk_util_pct, nvme_temp_c, net_tx_mbps, net_rx_mbps, net_latency_ms, packet_loss_pct, ecc_error_count, pcie_error_count, health_score, status_flags, source_vendor, source_model, payload_json) VALUES ('node:south_india:bangalore-0001', 'collector:south_india', 'south_india:bangalore', 'south_india-bangalore', 'bangalore.south_india.local', 'India', 'rack-1', 'south_india', 'Asia', to_timestamp(1779247241805 / 1000.0), to_timestamp(1779247241822 / 1000.0), 54.2, 71.4, 48.7, 62.1, 9220, 16384, 41024, 65536, 43.8, 228.5, 3100, FALSE, '', 67.3, 41.9, 180.4, 164.2, 4.5, 0.06, 1, 0, 74.6, 'nominal', 'generic-oem', 'edge-node-v2', '{"node_id":"south_india:bangalore","hostname":"bangalore.south_india.local","site_id":"india","region":"south_india","geo_region":"Asia"}') ON CONFLICT (message_id) DO NOTHING;
INSERT INTO node_minute_aggregates (bucket_start, node_id, site_id, region, geo_region, sample_count, min_cpu_temp_c, max_cpu_temp_c, avg_cpu_temp_c, avg_cpu_util_pct, avg_gpu_util_pct, avg_vram_used_pct, avg_mem_pressure_pct, avg_power_draw_w, avg_fan_rpm, throttle_count, alert_count, health_score_avg, health_score_min) VALUES (to_timestamp(1779247200000 / 1000.0), 'south_india:bangalore', 'india', 'south_india', 'Asia', 1, 54.2, 54.2, 54.2, 71.4, 62.1, 56.2, 43.8, 228.5, 3100, 0, 0, 74.6, 74.6) ON CONFLICT (bucket_start, node_id) DO UPDATE SET sample_count = EXCLUDED.sample_count, min_cpu_temp_c = LEAST(node_minute_aggregates.min_cpu_temp_c, EXCLUDED.min_cpu_temp_c), max_cpu_temp_c = GREATEST(node_minute_aggregates.max_cpu_temp_c, EXCLUDED.max_cpu_temp_c), avg_cpu_temp_c = EXCLUDED.avg_cpu_temp_c, avg_cpu_util_pct = EXCLUDED.avg_cpu_util_pct, avg_gpu_util_pct = EXCLUDED.avg_gpu_util_pct, avg_vram_used_pct = EXCLUDED.avg_vram_used_pct, avg_mem_pressure_pct = EXCLUDED.avg_mem_pressure_pct, avg_power_draw_w = EXCLUDED.avg_power_draw_w, avg_fan_rpm = EXCLUDED.avg_fan_rpm, health_score_avg = EXCLUDED.health_score_avg, health_score_min = EXCLUDED.health_score_min;
COMMIT;

